def procesar_lista(items: list) -> list:
    """Procesa items, registrando errores sin abortar."""
    resultados = []
    errores = []
    for item in items:
        try:
            resultados.append(int(item) * 2)
        except (ValueError, TypeError) as e:
            errores.append((item, str(e)))
    if errores:
        print(f"Advertencias: {errores}")
    return resultados

print(procesar_lista(["1", "2", "abc", "4"]))  # [2, 4, 8]

def dividir(a: float, b: float) -> float:
    if b == 0:
        raise ZeroDivisionError("El divisor no puede ser cero")
    return a / b

try:
    print(dividir(10, 2))  # 5.0
    print(dividir(10, 0))  # ZeroDivisionError
except ZeroDivisionError as e:
    print(f"Error: {e}")

