Write a function `FilterRepositoriesByStars` that takes the star range placeholder as input and returns a list of repositories that fall within the specified star range. The function should also handle cases where the star range is not provided or is invalid.

Example:
For the input `<gh_stars>100-500`, the function should retrieve repositories with star counts between 100 and 500.

### Solution:
```csharp
using System;
using System.Collections.Generic;
using System.Linq;

namespace Topshelf.DryIoc.Sample
{
    public class Repository
    {
        public string Name { get; set; }
        public int Stars { get; set; }
    }

    public class GitHubRepositoryProcessor
    {
        public List<Repository> Repositories { get; set; }

        public List<Repository> FilterRepositoriesByStars(string starRange)
        {
            if (string.IsNullOrWhiteSpace(starRange))
            {
                throw new ArgumentException("Star range is not provided.");
            }

            string[] rangeParts = starRange.Split('-');
            if (rangeParts.Length != 2 || !int.TryParse(rangeParts[0], out int lowerBound) || !int.TryParse(rangeParts[1], out int upperBound))
            {
                throw new ArgumentException("Invalid star range format.");
            }

            return Repositories.Where(repo => repo.Stars >= lowerBound && repo.Stars <= upperBound).ToList();
        }
    }
}
```

