    def __init__(self, name):
        self.name = name
        self.dependencies = []

    def add_dependency(self, dependency):
        self.dependencies.append(dependency)

    def execute(self):
        # Perform the migration logic here
        pass
```

The `execute_migrations` function should have the following signature:
```python
def execute_migrations(migrations):
    pass
```

Example:
```python
class MigrationA(Migration):
    def __init__(self):
        super().__init__('001_create_table_a')

    def execute(self):
        print('Executing migration A')

class MigrationB(Migration):
    def __init__(self):
        super().__init__('002_create_table_b')
        self.add_dependency('001_create_table_a')

    def execute(self):
        print('Executing migration B')

class MigrationC(Migration):
    def __init__(self):
        super().__init__('003_create_table_c')
        self.add_dependency('002_create_table_b')

    def execute(self):
        print('Executing migration C')

migrations = [MigrationA(), MigrationC(), MigrationB()]
execute_migrations(migrations)
```

Output:
```
Executing migration A
Executing migration B
Executing migration C
```

### Solution:
```python
class CircularDependencyError(Exception):
    pass

def execute_migrations(migrations):
    executed = set()

    def execute(migration):
        if migration.name in executed:
            return
        if migration.name in executing:
            raise CircularDependencyError("Circular dependency detected")
        executing.add(migration.name)
        for dependency in migration.dependencies:
            execute(dependency)
        migration.execute()
        executed.add(migration.name)
        executing.remove(migration.name)

    executing = set()
    for migration in migrations:
        execute(migration)
```

