### Solution:
```c
#include <stdio.h>
#include <stdlib.h>
#include <sys/time.h>
#include <sys/types.h>
#include <unistd.h>

int custom_select(int nfds, fd_set *readfds, fd_set *writefds, fd_set *exceptfds, struct timeval *timeout) {
    int max_fd = -1;
    fd_set readfds_copy, writefds_copy, exceptfds_copy;
    FD_ZERO(&readfds_copy);
    FD_ZERO(&writefds_copy);
    FD_ZERO(&exceptfds_copy);

    // Copy the file descriptor sets to avoid modifying the original sets
    if (readfds != NULL) {
        readfds_copy = *readfds;
        max_fd = update_max_fd(max_fd, readfds_copy);
    }
    if (writefds != NULL) {
        writefds_copy = *writefds;
        max_fd = update_max_fd(max_fd, writefds_copy);
    }
    if (exceptfds != NULL) {
        exceptfds_copy = *exceptfds;
        max_fd = update_max_fd(max_fd, exceptfds_copy);
    }

    // Use select-like logic to wait for file descriptors to become ready
    int ready_fds = 0;
    if (max_fd >= 0) {
        ready_fds = select(max_fd + 1, &readfds_copy, &writefds_copy, &exceptfds_copy, timeout);
    }

    if (ready_fds < 0) {
        perror("select");
        return -1;
    }

    // Update the original sets with the modified sets
    if (readfds != NULL) {
        *readfds = readfds_copy;
    }
    if (writefds != NULL) {
        *writefds = writefds_copy;
    }
    if (exceptfds != NULL) {
        *exceptfds = exceptfds_copy;
    }

    return ready_fds;
}

int update_max_fd(int max_fd, fd_set fds) {
    for (int i = 0; i < FD_SETSIZE; i++) {
        if (FD_ISSET(i, &fds) && i > max_fd) {
            max_fd = i;
        }
    }
    return max_fd;
}

int main() {
    // Example usage of custom_select
    fd_set readfds, writefds, exceptfds;
    FD_ZERO(&readfds);
    FD_ZERO(&writefds);
    FD_ZERO(&exceptfds);

    FD_SET(0, &readfds);  // Add stdin to readfds

    struct timeval timeout;
    timeout.tv_sec = 5;
    timeout.tv_usec = 0;

    int ready_fds = custom_select(1, &readfds, NULL, NULL, &timeout);
    if (ready_fds < 0) {
        printf("Error in custom_select\n");
    } else {
        printf("Number of ready file descriptors: %d\n", ready_fds);
    }

    return 0;
}
```

