Assumptions:
- The log file is a text file.
- The log file may contain multiple lines of text.
- The keyword may appear multiple times within a single line or across multiple lines.
- The keyword matching is case-sensitive.

Example:
For the following log file content (log.txt):
```
2022-01-01 10:00:00 - Error occurred: Disk full
2022-01-01 10:05:00 - Warning: Network connection lost
2022-01-01 10:10:00 - Error: Application crash
```
The function call `countKeywordOccurrences("log.txt", "Error")` should return 2, as the keyword "Error" appears twice in the log file.

### Solution:
```java
import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;

public class LogWatcher {
    public static int countKeywordOccurrences(String logFilePath, String keyword) {
        int count = 0;
        try (BufferedReader br = new BufferedReader(new FileReader(logFilePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                count += countOccurrencesInLine(line, keyword);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
        return count;
    }

    private static int countOccurrencesInLine(String line, String keyword) {
        int lastIndex = 0;
        int count = 0;
        while (lastIndex != -1) {
            lastIndex = line.indexOf(keyword, lastIndex);
            if (lastIndex != -1) {
                count++;
                lastIndex += keyword.length();
            }
        }
        return count;
    }

    public static void main(String[] args) {
        String logFilePath = "log.txt";
        String keyword = "Error";
        int occurrences = countKeywordOccurrences(logFilePath, keyword);
        System.out.println("Occurrences of '" + keyword + "' in " + logFilePath + ": " + occurrences);
    }
}
```

