```java
import javax.annotation.processing.AbstractProcessor;
import javax.annotation.processing.RoundEnvironment;
import javax.annotation.processing.SupportedAnnotationTypes;
import javax.lang.model.element.Element;
import javax.lang.model.element.ElementKind;
import javax.lang.model.element.ExecutableElement;
import javax.lang.model.element.TypeElement;
import javax.lang.model.type.DeclaredType;
import javax.lang.model.type.TypeMirror;
import javax.tools.Diagnostic;
import javax.tools.JavaFileObject;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Set;

@SupportedAnnotationTypes("info.smart_tools.smartactors.database_postgresql_plugins.postgres_db_tasks_plugin.DatabaseTask")
public class DatabaseTaskAnnotationProcessor extends AbstractProcessor {

    @Override
    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
        for (Element element : roundEnv.getElementsAnnotatedWith(DatabaseTask.class)) {
            if (element.getKind() == ElementKind.METHOD) {
                ExecutableElement methodElement = (ExecutableElement) element;
                TypeElement classElement = (TypeElement) methodElement.getEnclosingElement();
                String methodName = methodElement.getSimpleName().toString();
                String taskName = methodElement.getAnnotation(DatabaseTask.class).name();
                int priority = methodElement.getAnnotation(DatabaseTask.class).priority();

                try {
                    generateDatabaseTaskPlugin(classElement, methodName, taskName, priority);
                } catch (IOException e) {
                    processingEnv.getMessager().printMessage(Diagnostic.Kind.ERROR, "Error generating DatabaseTaskPlugin: " + e.getMessage());
                }
            }
        }
        return true;
    }

    private void generateDatabaseTaskPlugin(TypeElement classElement, String methodName, String taskName, int priority) throws IOException {
        String packageName = processingEnv.getElementUtils().getPackageOf(classElement).getQualifiedName().toString();
        String className = "DatabaseTaskPlugin";

        JavaFileObject file = processingEnv.getFiler().createSourceFile(packageName + "." + className);
        try (PrintWriter writer = new PrintWriter(file.openWriter())) {
            writer.println("package " + packageName + ";");
            writer.println();
            writer.println("import info.smart_tools.smartactors.database.interfaces.idatabase_task.IDatabaseTask;");
            writer.println("import info.smart_tools.smartactors.database.interfaces.idatabase_task.exception.DatabaseTaskException;");
            writer.println("import info.smart_tools.smartactors.database.interfaces.idatabase_task.exception.DatabaseTaskHandlerNotFoundException;");
            writer.println("import info.smart_tools.smartactors.database.interfaces.idatabase_task.exception.DatabaseTaskRegistrationException;");
            writer.println("import info.smart_tools.smartactors.database_postgresql.postgres_task.PostgresTask;");
            writer.println();
            writer.println("public class " + className + " {");
            writer.println("    static {");
            writer.println("        try {");

            // Generate code to register the database task handler
            writer.println("            IDatabaseTask task = new PostgresTask(\"" + taskName + "\");");
            if (priority > 0) {
                writer.println("            // Register " + methodName + " with priority " + priority);
            } else {
                writer.println("            // Register " + methodName + " with default priority");
            }

            writer.println("        } catch (DatabaseTaskRegistrationException | DatabaseTaskHandlerNotFoundException | DatabaseTaskException e) {");
            writer.println("            e.printStackTrace();");
            writer.println("        }");
            writer.println("    }");
            writer.println("}");
        }
    }
}
