class WKRStack {
    private int[] stackArray;
    private int top;

    public WKRStack(int capacity) {
        stackArray = new int[capacity];
        top = -1;
    }

    public void push(int val) {
        if (top == stackArray.length - 1) {
            // Stack is full, throw an exception or resize the array
            throw new IllegalStateException("Stack is full");
        }
        stackArray[++top] = val;
    }

    public int pop() {
        if (isEmpty()) {
            // Stack is empty, throw an exception or return a specific value
            throw new IllegalStateException("Stack is empty");
        }
        return stackArray[top--];
    }

    public int peek() {
        if (isEmpty()) {
            // Stack is empty, throw an exception or return a specific value
            throw new IllegalStateException("Stack is empty");
        }
        return stackArray[top];
    }

    public boolean isEmpty() {
        return top == -1;
    }
}
```

