### Solution:
```python
import requests

class DatabaseQueryError(Exception):
    pass

def execute_query_https(query: str, user: str = None, enable_ssl_auth: bool = True, cert_name: str = None) -> str:
    try:
        if enable_ssl_auth:
            if cert_name:
                response = requests.get("https://database-url", verify=cert_name)
            else:
                raise DatabaseQueryError("SSL certificate name not provided")
        else:
            response = requests.get("https://database-url", verify=False)

        if response.status_code == 200:
            return "Query executed successfully"
        else:
            raise DatabaseQueryError(f"Query execution failed with status code {response.status_code}")
