class Node {
    int data;
    Node next;

    Node(int data) {
        this.data = data;
        this.next = null;
    }
}

class Stack {
    private Node top;

    public Stack() {
        this.top = null;
    }

    public void push(int val) {
        Node newNode = new Node(val);
        newNode.next = top;
        top = newNode;
    }

    public int pop() {
        if (top == null) {
            throw new IllegalStateException("Stack is empty");
        }
        int val = top.data;
        top = top.next;
        return val;
    }

    public int peek() {
        if (top == null) {
            throw new IllegalStateException("Stack is empty");
        }
        return top.data;
    }

    public boolean isEmpty() {
        return top == null;
    }
}

// Example usage
Stack stack = new Stack();
stack.push(5);
stack.push(10);
System.out.println(stack.peek()); // Output: 10
System.out.println(stack.pop()); // Output: 10
System.out.println(stack.isEmpty()); // Output: false
System.out.println(stack.pop()); // Output: 5
System.out.println(stack.isEmpty()); // Output: true
```

