1. `Push`: Add an element to the top of the stack.
2. `Pop`: Remove and return the element at the top of the stack.
3. `Peek`: Return the element at the top of the stack without removing it.
4. `IsEmpty`: Return true if the stack is empty, false otherwise.

Your implementation should use a generic list as the underlying data structure to store the elements.

Your task is to complete the implementation of the `CustomStack` class by filling in the missing code for the specified operations.

```csharp
using System;
using System.Collections.Generic;

public class CustomStack<T>
{
    private List<T> elements;

    public CustomStack()
    {
        elements = new List<T>();
    }

    public void Push(T item)
    {
        // Add the item to the top of the stack
        elements.Add(item);
    }

    public T Pop()
    {
        // Remove and return the element at the top of the stack
        if (IsEmpty())
        {
            throw new InvalidOperationException("Stack is empty");
        }
        T item = elements[elements.Count - 1];
        elements.RemoveAt(elements.Count - 1);
        return item;
    }

    public T Peek()
    {
        // Return the element at the top of the stack without removing it
        if (IsEmpty())
        {
            throw new InvalidOperationException("Stack is empty");
        }
        return elements[elements.Count - 1];
    }

    public bool IsEmpty()
    {
        // Return true if the stack is empty, false otherwise
        return elements.Count == 0;
    }
}
