### Solution:
```csharp
using System;

public class FundsDepositedEventArgs : EventArgs
{
    public decimal Amount { get; }

    public FundsDepositedEventArgs(decimal amount)
    {
        Amount = amount;
    }
}

public class FundsWithdrawnEventArgs : EventArgs
{
    public decimal Amount { get; }

    public FundsWithdrawnEventArgs(decimal amount)
    {
        Amount = amount;
    }
}

public class BankAccount
{
    public event EventHandler<FundsDepositedEventArgs> FundsDeposited;
    public event EventHandler<FundsWithdrawnEventArgs> FundsWithdrawn;

    private decimal balance;

    public BankAccount(decimal initialBalance)
    {
        balance = initialBalance;
    }

    public void Deposit(decimal amount)
    {
        balance += amount;
        OnFundsDeposited(amount);
    }

    public void Withdraw(decimal amount)
    {
        if (amount <= balance)
        {
            balance -= amount;
            OnFundsWithdrawn(amount);
        }
        else
        {
            throw new InvalidOperationException("Insufficient funds");
        }
    }

    public decimal CalculateInterest(int months)
    {
        decimal interestRate = 0.03m; // 3% per annum
        decimal interest = balance * (interestRate / 12) * months;
        return interest;
    }

    protected virtual void OnFundsDeposited(decimal amount)
    {
        FundsDeposited?.Invoke(this, new FundsDepositedEventArgs(amount));
    }

    protected virtual void OnFundsWithdrawn(decimal amount)
    {
        FundsWithdrawn?.Invoke(this, new FundsWithdrawnEventArgs(amount));
    }
}
```

