from typing import List
import json

class Book:
    def __init__(self, title: str, author: str, isbn: str):
        self.title = title
        self.author = author
        self.isbn = isbn

class BookLibrary:
    def __init__(self):
        self.library = {}

    def add_book(self, title: str, author: str, isbn: str):
        if isbn in self.library:
            raise DuplicateISBNError(f"Book with ISBN {isbn} already exists in the library")
        self.library[isbn] = Book(title, author, isbn)

    def remove_book(self, isbn: str):
        if isbn not in self.library:
            raise BookNotFoundError(f"Book with ISBN {isbn} does not exist in the library")
        del self.library[isbn]

    def search_book(self, title: str) -> List[str]:
        return [book.author for book in self.library.values() if title.lower() in book.title.lower()]

    def save_library(self, file_path: str):
        with open(file_path, 'w') as file:
            json.dump({isbn: {'title': book.title, 'author': book.author} for isbn, book in self.library.items()}, file)

    def load_library(self, file_path: str):
        try:
            with open(file_path, 'r') as file:
                data = json.load(file)
                self.library = {isbn: Book(info['title'], info['author'], isbn) for isbn, info in data.items()}
        except FileNotFoundError:
            raise FileNotFoundError(f"File '{file_path}' not found")

class DuplicateISBNError(Exception):
    pass

class BookNotFoundError(Exception):
    pass
```

