import io.netty.buffer.ByteBuf;
import io.netty.channel.ChannelHandlerContext;
import io.netty.handler.codec.MessageToByteEncoder;
import io.netty.handler.codec.ByteToMessageDecoder;
import java.util.List;

public final class SpawnXpOrbCodec extends MessageToByteEncoder<SpawnXpOrbMessage> implements ByteToMessageDecoder<SpawnXpOrbMessage> {
    @Override
    protected void encode(ChannelHandlerContext ctx, SpawnXpOrbMessage message, ByteBuf out) throws Exception {
        out.writeInt(message.getEntityId());
        out.writeInt(message.getPosX());
        out.writeInt(message.getPosY());
        out.writeInt(message.getPosZ());
        out.writeInt(message.getXpValue());
    }

    @Override
    protected void decode(ChannelHandlerContext ctx, ByteBuf in, List<Object> out) throws Exception {
        if (in.readableBytes() < 20) {
            return; // Insufficient data to decode the message
        }
        int entityId = in.readInt();
        int posX = in.readInt();
        int posY = in.readInt();
        int posZ = in.readInt();
        int xpValue = in.readInt();
        SpawnXpOrbMessage spawnXpOrbMessage = new SpawnXpOrbMessage(entityId, posX, posY, posZ, xpValue);
        out.add(spawnXpOrbMessage);
    }
}
