import traceback
import multiprocessing

class ProcessManager:
    def __init__(self):
        self.processes = {}

    def create_process(self, name, target):
        if name in self.processes:
            raise ValueError("Process with the same name already exists")
        self.processes[name] = multiprocessing.Process(name=name, target=target)

    def start_process(self, name):
        if name not in self.processes:
            raise ValueError("Process does not exist")
        self.processes[name].start()

    def terminate_process(self, name):
        if name not in self.processes:
            raise ValueError("Process does not exist")
        self.processes[name].terminate()
        del self.processes[name]

    def handle_exception(self, name):
        if name not in self.processes:
            raise ValueError("Process does not exist")
        try:
            self.processes[name].join()
        except:
            traceback.print_exc()
            self.processes[name].terminate()
            del self.processes[name]
```

