class AttributeNamingMeta(type):
    def __new__(cls, name, bases, dct):
        for attr_name in dct:
            if not attr_name.endswith('_attr') and not attr_name.startswith('__'):
                raise ValueError(f"Attribute name '{attr_name}' does not end with '_attr'")
        return super().__new__(cls, name, bases, dct)

