def argscope(allowed_args):
    def decorator(func):
        def wrapper(*args, **kwargs):
            for arg in kwargs:
                if arg not in allowed_args:
                    raise ValueError(f"Invalid argument '{arg}' provided")
            return func(*args, **kwargs)
        return wrapper
    return decorator

# Example usage:
