```java
import javax.annotation.processing.AbstractProcessor;
import javax.annotation.processing.RoundEnvironment;
import javax.annotation.processing.SupportedAnnotationTypes;
import javax.lang.model.element.Element;
import javax.lang.model.element.ElementKind;
import javax.lang.model.element.Modifier;
import javax.lang.model.element.TypeElement;
import javax.lang.model.type.DeclaredType;
import javax.lang.model.type.MirroredTypeException;
import javax.lang.model.type.TypeMirror;
import javax.tools.Diagnostic;
import javax.tools.JavaFileObject;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Set;

@SupportedAnnotationTypes("com.example.CustomValidation")
public class CustomValidationProcessor extends AbstractProcessor {

    @Override
    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
        for (Element element : roundEnv.getElementsAnnotatedWith(CustomValidation.class)) {
            if (element.getKind() == ElementKind.FIELD) {
                TypeElement classElement = (TypeElement) element.getEnclosingElement();
                String className = classElement.getSimpleName().toString();
                String fieldName = element.getSimpleName().toString();
                CustomValidation annotation = element.getAnnotation(CustomValidation.class);
                int min = annotation.min();
                int max = annotation.max();

                generateValidationClass(className, fieldName, min, max);
            }
        }
        return true;
    }

    private void generateValidationClass(String className, String fieldName, int min, int max) {
        String validationClassName = className + "Validation";
        String validationMethodName = "validate" + fieldName.substring(0, 1).toUpperCase() + fieldName.substring(1);

        try {
            JavaFileObject file = processingEnv.getFiler().createSourceFile("com.example." + validationClassName);
            try (PrintWriter writer = new PrintWriter(file.openWriter())) {
                writer.println("package com.example;");
                writer.println("public class " + validationClassName + " {");
                writer.println("    public static void " + validationMethodName + "(String " + fieldName + ") {");
                writer.println("        if (" + fieldName + " == null || " + fieldName + ".length() < " + min + " || " + fieldName + ".length() > " + max + ") {");
                writer.println("            throw new IllegalArgumentException(\"" + fieldName.substring(0, 1).toUpperCase() + fieldName.substring(1) + " must be between " + min + " and " + max + " characters\");");
                writer.println("        }");
                writer.println("    }");
                writer.println("}");
            }
        } catch (IOException e) {
            processingEnv.getMessager().printMessage(Diagnostic.Kind.ERROR, "Error creating file: " + e.getMessage());
        }
    }
}
```

