import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.Scanner;
import java.util.zip.DeflaterOutputStream;
import java.util.zip.InflaterOutputStream;
import java.util.zip.ZipException;

public class CompressionDecompression {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a string: ");
        String input = scanner.nextLine();

        System.out.print("Choose an operation (1 for compression, 2 for decompression): ");
        int choice = scanner.nextInt();

        if (choice == 1) {
            try {
                ByteArrayOutputStream baos = new ByteArrayOutputStream();
                DeflaterOutputStream dos = new DeflaterOutputStream(baos);
                dos.write(input.getBytes());
                dos.close();
                System.out.println("Compressed data: " + baos.toString());
            } catch (IOException e) {
                System.out.println("Error during compression: " + e.getMessage());
            }
        } else if (choice == 2) {
            try {
                byte[] compressedData = input.getBytes();
                ByteArrayInputStream bais = new ByteArrayInputStream(compressedData);
                ByteArrayOutputStream baos = new ByteArrayOutputStream();
                InflaterOutputStream ios = new InflaterOutputStream(baos);
                byte[] buffer = new byte[1024];
                int len;
                while ((len = bais.read(buffer)) > 0) {
                    ios.write(buffer, 0, len);
                }
                ios.close();
                System.out.println("Decompressed data: " + baos.toString());
            } catch (ZipException e) {
                System.out.println("Error: Invalid compressed data format");
            } catch (IOException e) {
                System.out.println("Error during decompression: " + e.getMessage());
            }
        } else {
            System.out.println("Invalid choice. Please choose 1 for compression or 2 for decompression.");
        }
    }
}
```

