    def __init__(self, cmap):
        self.cmap = cmap

    def to_rgb(self, value: float) -> str:
        color = self.cmap.to_rgba(value, bytes=True)[:3]
        color = 'rgb({})'.format(', '.join([str(c) for c in color]))
        return color


class PatternContinousColors(ContinousColors):
