### Solution:
```csharp
using System;
using System.Collections.Generic;
using System.Linq;

namespace ConspectoPatronum.Domain
{
    public interface IRepository<T> where T : IEntity
    {
        T GetById(int id);
        IEnumerable<T> GetAll();
        void Add(T entity);
        void Update(T entity);
        void Delete(T entity);
    }

    public class Repository<T> : IRepository<T> where T : IEntity
    {
        private readonly List<T> _entities;

        public Repository()
        {
            _entities = new List<T>();
        }

        public T GetById(int id)
        {
            return _entities.FirstOrDefault(e => e.Id == id);
        }

        public IEnumerable<T> GetAll()
        {
            return _entities;
        }

        public void Add(T entity)
        {
            if (entity == null)
            {
                throw new ArgumentNullException(nameof(entity));
            }
            _entities.Add(entity);
        }

        public void Update(T entity)
        {
            if (entity == null)
            {
                throw new ArgumentNullException(nameof(entity));
            }
            // Assuming the entity has an Id property
            var existingEntity = _entities.FirstOrDefault(e => e.Id == entity.Id);
            if (existingEntity != null)
            {
                // Update the existing entity with the new values
                // For simplicity, we assume T has properties that can be updated directly
                existingEntity = entity;
            }
            else
            {
                throw new InvalidOperationException("Entity not found in the repository.");
            }
        }

        public void Delete(T entity)
        {
            if (entity == null)
            {
                throw new ArgumentNullException(nameof(entity));
            }
            _entities.Remove(entity);
        }
    }
}
```
This solution provides a generic repository interface `IRepository<T>` and a concrete implementation `Repository<T>` that supports basic CRUD operations for any entity type `T` that implements the `IEntity` interface. The `Repository<T>` class uses a simple in-memory storage for the entities and ensures type safety by constraining `T` to implement the `IEntity` interface.

