# Import the necessary library for parsing
import pyauparser

# Define the parse_string_to_tree function
def parse_string_to_tree(grammar, expr):
    try:
        tree = pyauparser.parse_string_to_tree(grammar, expr)
        return tree
    except pyauparser.ParseError as e:
        raise e

# Define the evaluate function to recursively evaluate the parse tree
def evaluate(node, grammar):
    if node.type == 'number':
        return int(node.value)
    elif node.type == 'unary':
        if node.value == '-':
            return -evaluate(node.children[0], grammar)
    elif node.type == 'binary':
        left = evaluate(node.children[0], grammar)
        right = evaluate(node.children[1], grammar)
        if node.value == '+':
            return left + right
        elif node.value == '-':
            return left - right
        elif node.value == '*':
            return left * right
        elif node.value == '/':
            return left / right
    else:
        raise ValueError("Invalid node type")

