        self.file_path = file_path
        self.__config = {}  # Initialize settings data as a dictionary
        self.load_settings()  # Load settings data from the file upon initialization

    def update_setting(self, category, key, value):
        try:
            if category in self.__config:
                self.__config[category][key] = value
            else:
                self.__config[category] = {key: value}
        except Exception as e:
            raise ValueError(f"Failed to update setting: {e}")

    def save_settings(self):
        try:
            with open(self.file_path, 'w') as file:
                # Write the updated settings data to the file
                file.write(str(self.__config))
        except Exception as e:
            raise IOError(f"Failed to save settings to file: {e}")

    def load_settings(self):
        try:
            with open(self.file_path, 'r') as file:
                # Load settings data from the file
                data = file.read()
                self.__config = eval(data)  # Convert the string representation of dictionary to actual dictionary
        except Exception as e:
