```java
import javax.annotation.processing.AbstractProcessor;
import javax.annotation.processing.RoundEnvironment;
import javax.annotation.processing.SupportedAnnotationTypes;
import javax.lang.model.element.Element;
import javax.lang.model.element.ElementKind;
import javax.lang.model.element.Modifier;
import javax.lang.model.element.TypeElement;
import javax.lang.model.type.TypeMirror;
import javax.tools.Diagnostic;
import javax.tools.JavaFileObject;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Set;

@SupportedAnnotationTypes("Validation")
public class ValidationProcessor extends AbstractProcessor {

    @Override
    public boolean process(Set<? extends TypeElement> annotations, RoundEnvironment roundEnv) {
        for (Element element : roundEnv.getElementsAnnotatedWith(Validation.class)) {
            if (element.getKind() == ElementKind.FIELD) {
                String fieldName = element.getSimpleName().toString();
                TypeMirror fieldType = element.asType();
                Validation validation = element.getAnnotation(Validation.class);
                generateValidationCode(fieldName, fieldType, validation);
            }
        }
        return true;
    }

    private void generateValidationCode(String fieldName, TypeMirror fieldType, Validation validation) {
        String validationCode = "";
        if (fieldType.getKind().isPrimitive()) {
            validationCode += "if (" + fieldName + " < " + validation.min() + " || " + fieldName + " > " + validation.max() + ") {\n";
            validationCode += "    throw new IllegalArgumentException(\"" + fieldName + " must be between " + validation.min() + " and " + validation.max() + "\");\n";
            validationCode += "}\n";
        } else if (fieldType.toString().equals("java.lang.String")) {
            validationCode += "if (" + fieldName + ".length() < " + validation.min() + " || " + fieldName + ".length() > " + validation.max() + ") {\n";
            validationCode += "    throw new IllegalArgumentException(\"" + fieldName + " length must be between " + validation.min() + " and " + validation.max() + "\");\n";
            validationCode += "}\n";
            if (validation.notEmpty()) {
                validationCode += "if (" + fieldName + ".isEmpty()) {\n";
                validationCode += "    throw new IllegalArgumentException(\"" + fieldName + " must not be empty\");\n";
                validationCode += "}\n";
            }
        }
        writeGeneratedCode(fieldName, validationCode);
    }

    private void writeGeneratedCode(String fieldName, String validationCode) {
        try {
            JavaFileObject fileObject = processingEnv.getFiler().createSourceFile(fieldName + "Validator");
            try (PrintWriter out = new PrintWriter(fileObject.openWriter())) {
                out.println("public class " + fieldName + "Validator {");
                out.println("    public void validate(" + fieldName + " " + fieldName + ") {");
                out.println(validationCode);
                out.println("    }");
                out.println("}");
            }
        } catch (IOException e) {
            processingEnv.getMessager().printMessage(Diagnostic.Kind.ERROR, "Error generating validation code for " + fieldName + ": " + e.getMessage());
        }
    }
}
```

In this solution, the `ValidationProcessor` class is an annotation processor that processes elements annotated with `@Validation`. It generates validation code based on the annotation attributes and the type of the annotated field. The `generateValidationCode` method constructs the validation code based on the field type and the `@Validation` attributes, and the `writeGeneratedCode` method writes the generated code to a new Java file. The generated code includes the necessary validation checks based on the specified criteria.

### Problem:
You are tasked with implementing a simple stack data structure in Java. Your stack should support the following operations:
1. `push(int val)`: Add an element to the top of the stack.
2. `pop()`: Remove the element at the top of the stack and return its value.
3. `peek()`: Return the value of the element at the top of the stack without removing it.
4. `isEmpty()`: Return true if the stack is empty, false otherwise.

You are given the following code snippet as a starting point for your implementation:
```java
public class MyStack {
    // Your implementation here
    return this;
}
```

Your task is to complete the `MyStack` class by implementing the stack operations using an underlying array or any other suitable data structure. Ensure that your implementation follows the principles of a stack data structure and supports the specified operations efficiently.

### Solution:
```java
public class MyStack {
    private int[] stackArray;
    private int top;

    public MyStack(int capacity) {
        stackArray = new int[capacity];
        top = -1;
    }

    public void push(int val) {
        if (top == stackArray.length - 1) {
            // Stack is full, need to resize or throw an exception
            // For simplicity, we'll assume resizing the array
            int[] newArray = new int[stackArray.length * 2];
            System.arraycopy(stackArray, 0, newArray, 0, stackArray.length);
            stackArray = newArray;
        }
        stackArray[++top] = val;
    }

    public int pop() {
        if (isEmpty()) {
            throw new EmptyStackException();
        }
        return stackArray[top--];
    }

    public int peek() {
        if (isEmpty()) {
            throw new EmptyStackException();
        }
        return stackArray[top];
    }

    public boolean isEmpty() {
        return top == -1;
    }
}
```

This implementation of the `MyStack` class uses an array as the underlying data structure to support the stack operations efficiently. The `push` operation adds elements to the top of the stack, resizing the array if necessary. The `pop` operation removes and returns the top element, while the `peek` operation returns the top element without removing it. The `isEmpty` operation checks if the stack is empty.

