```java
public class QueueManager {
    // Inner class representing a node in the linked list
    private class Node {
        String data;
        Node next;

        Node(String data) {
            this.data = data;
            this.next = null;
        }
    }

    private Node front;
    private Node rear;

    // Constructor to initialize an empty queue
    public QueueManager() {
        front = null;
        rear = null;
    }

    // Add a new task to the end of the queue
    public void enqueue(String task) {
        Node newNode = new Node(task);
        if (rear == null) {
            front = newNode;
            rear = newNode;
        } else {
            rear.next = newNode;
            rear = newNode;
        }
    }

    // Remove and return the task at the front of the queue
    public String dequeue() {
        if (front == null) {
            throw new NoSuchElementException("Queue is empty");
        }
        String data = front.data;
        front = front.next;
        if (front == null) {
            rear = null;
        }
        return data;
    }

    // Return the task at the front of the queue without removing it
    public String peek() {
        if (front == null) {
            throw new NoSuchElementException("Queue is empty");
        }
        return front.data;
    }

    // Return true if the queue is empty, false otherwise
    public boolean isEmpty() {
        return front == null;
    }
}
```

This solution provides a complete implementation of the `QueueManager` class using a linked list to support the specified operations.

