import subprocess

class CustomCodecs:
    COMMAND = 'iconv'  # Default location for iconv

    @classmethod
    def register_codec(cls, name, codec):
        setattr(cls, name, codec)

    @classmethod
    def set_iconv_location(cls, location):
        cls.COMMAND = location

    @classmethod
    def encode(cls, data, encoding, errors='strict'):
        try:
            result = subprocess.check_output([cls.COMMAND, '-t', encoding, '-f', 'utf-8', '-c', '-'], input=data.encode(), stderr=subprocess.STDOUT)
            return result.decode(encoding, errors=errors)
        except subprocess.CalledProcessError as e:
            if errors == 'ignore':
                return ''
            else:
                raise ValueError(f"Error encoding data: {e.output.decode()}")

    @classmethod
    def decode(cls, data, encoding, errors='strict'):
        try:
            result = subprocess.check_output([cls.COMMAND, '-t', 'utf-8', '-f', encoding, '-c', '-'], input=data.encode(), stderr=subprocess.STDOUT)
            return result.decode(encoding, errors=errors)
        except subprocess.CalledProcessError as e:
            if errors == 'ignore':
                return ''
            else:
                raise ValueError(f"Error decoding data: {e.output.decode()}")

