import json

def validate_cfn_properties(properties, spec_file):
    with open(spec_file) as f:
        spec = json.load(f)

    def validate_property(value, spec):
        if spec["type"] == "string":
            if not isinstance(value, str):
                raise TypeError(f"Expected string value for property '{name}', but got {type(value).__name__}")
        elif spec["type"] == "integer":
            if not isinstance(value, int):
                raise TypeError(f"Expected integer value for property '{name}', but got {type(value).__name__}")
        elif spec["type"] == "array":
            if not isinstance(value, list):
                raise TypeError(f"Expected array value for property '{name}', but got {type(value).__name__}")
            item_type = spec.get("itemType", "string")
            for item in value:
                validate_property(item, {"type": item_type})
        elif spec["type"] == "object":
            if not isinstance(value, dict):
                raise TypeError(f"Expected object value for property '{name}', but got {type(value).__name__}")
            properties_spec = spec.get("properties")
            if properties_spec:
                for name, sub_value in value.items():
                    sub_spec = properties_spec.get(name)
                    if sub_spec:
                        validate_property(sub_value, sub_spec)
                    else:
                        raise KeyError(f"Unexpected property '{name}' for object property '{name}'")
        else:
            raise ValueError(f"Invalid type '{spec['type']}' in specification")

    for name, spec in spec["properties"].items():
        if name not in properties:
            raise KeyError(f"Missing required property '{name}'")
        value = properties[name]
        validate_property(value, spec)

    return properties
```

