def binary_to_decimal(binary_string, base=2):
    if base != 2:
        raise ValueError("Base must be 2 for binary conversion.")
    try:
        decimal_value = int(binary_string, base)
    except ValueError:
        raise ValueError("Invalid binary string")
    return decimal_value

def decimal_to_binary(decimal_value, base=2):
    if base != 2:
        raise ValueError("Base must be 2 for binary conversion.")
    binary_string = bin(decimal_value)[2:]
    return binary_string

def convert_binary_or_decimal(value, base=None):
    if base is None:
        if isinstance(value, str):
            return binary_to_decimal(value)
        elif isinstance(value, int):
            return decimal_to_binary(value)
        else:
            raise TypeError("Value must be a string or an integer.")
    else:
        if isinstance(value, str):
            return binary_to_decimal(value, base)
        elif isinstance(value, int):
            return decimal_to_binary(value, base)
        else:
            raise TypeError("Value must be a string or an integer.")
